-- Imperial Novel 16.19.0: AI Author Studio
-- Runtime bootstrap in src/index.js also creates these tables for deployments
-- where the migration is not applied manually.
CREATE TABLE IF NOT EXISTS ai_author_projects (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_user_id INTEGER NOT NULL, novel_id INTEGER, name TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'manual', status TEXT NOT NULL DEFAULT 'draft', genre TEXT DEFAULT '', fandom TEXT DEFAULT '', premise TEXT DEFAULT '', protagonist TEXT DEFAULT '', settings_json TEXT NOT NULL DEFAULT '{}', bible_json TEXT NOT NULL DEFAULT '{}', auto_publish INTEGER NOT NULL DEFAULT 0, chapters_target INTEGER NOT NULL DEFAULT 0, chapters_generated INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_chapter_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, owner_user_id INTEGER NOT NULL, chapter_number INTEGER NOT NULL, job_type TEXT NOT NULL DEFAULT 'draft', status TEXT NOT NULL DEFAULT 'queued', prompt TEXT DEFAULT '', result TEXT DEFAULT '', error TEXT DEFAULT '', attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, started_at TEXT, finished_at TEXT);
CREATE TABLE IF NOT EXISTS ai_generation_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, owner_user_id INTEGER NOT NULL, agent TEXT NOT NULL, mode TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ok', input_summary TEXT DEFAULT '', output_summary TEXT DEFAULT '', provider TEXT DEFAULT 'local', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_provider_benchmarks (id INTEGER PRIMARY KEY AUTOINCREMENT, provider TEXT NOT NULL, observed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, chapters_delta INTEGER NOT NULL DEFAULT 0, interval_seconds INTEGER NOT NULL DEFAULT 0, source_url TEXT DEFAULT '', access_mode TEXT DEFAULT 'public-metadata', confidence TEXT DEFAULT 'unknown');
CREATE TABLE IF NOT EXISTS ai_publish_policies (project_id INTEGER PRIMARY KEY, require_rights INTEGER NOT NULL DEFAULT 1, require_review INTEGER NOT NULL DEFAULT 1, max_chapters_per_day INTEGER NOT NULL DEFAULT 10, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
